70	 */
71	
72	@RestController
73	@CrossOrigin(exposedHeaders = "errors, content-type")
74	@RequestMapping("/api")
75	public class OwnerRestControllerV1 implements OwnersApi {
76	
77	    /**
78	     * Syntactic check for an email address: a non-empty local part, a single {@code @}, and a
79	     * domain containing at least one dot, with no whitespace in any part.
80	     */
81	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
82	
83	    /**
84	     * Email domains belonging to disposable/throwaway mail providers. An owner whose email domain
85	     * (the part after the {@code @}, compared case-insensitively) is listed here is rejected: such
86	     * addresses are not durable contact details. Entries are stored lower-cased.
87	     */
88	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
89	        "mailinator.com",
90	        "tempmail.com",
91	        "guerrillamail.com");
92	
93	    /**
94	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
95	     * new owner's id, customer code, registration date, membership level and membership number.
96	     */
97	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
98	
99	    /**
100	     * Common street-type abbreviations expanded during address normalization. Keys are the
101	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
102	     * expanded form it is replaced with.
103	     */
104	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
105	        "ST", "STREET",
106	        "RD", "ROAD",
107	        "AVE", "AVENUE");
108	
109	    /**
110	     * The maximum number of owners a single city may contain. Once a city holds this many owners it
111	     * is at capacity and cannot take any more.
112	     */
113	    private static final int CITY_CAPACITY = 50;
114	
115	    /**
116	     * The maximum number of owners that may be registered in a single day. Once this many owners
117	     * already carry today's {@code registrationDate}, the day's quota is exhausted and no further
118	     * owners can be created that day.
119	     */
120	    private static final int DAILY_OWNER_LIMIT = 100;
121	
122	    /**
123	     * The number of owners that may be registered on a single business day before a response starts
124	     * carrying a {@code bulkSignupWarning}. Once <em>more than</em> this many owners already carry the
125	     * current business day's {@code registrationDate}, that day's signups are flagged as unusually
126	     * high volume.
127	     */
128	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
129	
130	    /**
131	     * Fixed public holidays that the business-day roll skips over. A registration date that lands on
132	     * one of these dates is rolled forward to the next non-holiday business day, exactly as a weekend
133	     * date is rolled forward off a Saturday or Sunday.
134	     */
135	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
136	        LocalDate.parse("2026-01-01"),
137	        LocalDate.parse("2026-01-26"),
138	        LocalDate.parse("2026-04-25"),
139	        LocalDate.parse("2026-12-25"),
140	        LocalDate.parse("2026-12-28"));
141	
142	    /**
143	     * E.164 country codes mapped to the exact number of national (significant) digits a telephone for
144	     * that country must carry. For example {@code '+61'} (Australia) requires 9 national digits and
145	     * {@code '+1'} (NANP) requires 10. A country code listed here enforces that national-number length;
146	     * a number whose country code is not listed is accepted at any otherwise-valid E.164 length.
147	     */
148	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
149	        "61", 9,
150	        "1", 10);
151	
152	    /**
153	     * Fixed region-to-postcode-range lookup used both to validate an owner's optional postcode against
154	     * the region derived from the owner's city ({@link #regionForCity}) and to derive the postcode's own
155	     * region for the {@code customerCode} ({@link #regionForPostcode}). Each value is the inclusive
156	     * {@code {low, high}} 4-digit range for that region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A
157	     * region that is not listed ({@code 'UNKNOWN'}) carries no range and accepts any 4-digit postcode.
158	     */
159	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
160	        "NSW", new int[] {2000, 2099},
161	        "VIC", new int[] {3000, 3099},
162	        "QLD", new int[] {4000, 4099});
163	
164	    /**
165	     * Fixed city-to-region lookup used to validate an owner's optional postcode against the region
166	     * derived from the owner's city. Any city not listed has region {@code 'UNKNOWN'} and so accepts
167	     * any 4-digit postcode.
168	     */
169	    private static final Map<String, String> CITY_REGION = Map.of(
170	        "Sydney", "NSW",
171	        "Melbourne", "VIC",
172	        "Brisbane", "QLD");
173	
174	    /**
175	     * Remembers the owner created for each {@code Idempotency-Key} seen on a create request, keyed by
176	     * the header value. A repeated create carrying a key already present here is served the originally
177	     * created owner instead of creating a duplicate, so retries are safe. The map only ever grows with
178	     * distinct keys and is held for the application's lifetime, consistent with the in-memory, single
179	     * instance scope of this sample.
180	     */
181	    private final Map<String, Integer> idempotentCreateOwnerIds = new ConcurrentHashMap<>();
182	
183	    private final ClinicService clinicService;
184	
185	    private final OwnerMapper ownerMapper;
186	
187	    private final PetMapper petMapper;
188	
189	    private final VisitMapper visitMapper;
190	
191	    public OwnerRestControllerV1(ClinicService clinicService,
192	                                 OwnerMapper ownerMapper,
193	                                 PetMapper petMapper,
194	                                 VisitMapper visitMapper) {
195	        this.clinicService = clinicService;
196	        this.ownerMapper = ownerMapper;
197	        this.petMapper = petMapper;
198	        this.visitMapper = visitMapper;
199	    }
200	
201	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
202	    @Override
203	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
204	        Collection<Owner> owners;
205	        if (lastName != null) {
206	            owners = this.clinicService.findOwnerByLastName(lastName);
207	        } else {
208	            owners = this.clinicService.findAllOwners();
209	        }
210	        if (owners.isEmpty()) {
211	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
212	        }
213	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
214	    }
215	
216	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
217	    @Override
218	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
219	        Owner owner = this.clinicService.findOwnerById(ownerId);
220	        if (owner == null) {
221	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
222	        }
223	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
224	        applyBulkSignupWarning(ownerDto);
225	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
226	    }
227	
228	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
229	    @Override
230	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
231	        ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
232	        if (replay != null) {
233	            return replay;
234	        }
235	        validateRequiredFields(ownerFieldsDto);
236	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
237	        LocalDate registrationDate = toBusinessDay(
238	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now());
239	        rejectDailyLimitReached(registrationDate);
240	        HttpHeaders headers = new HttpHeaders();
241	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
242	        applyAddress(owner, ownerFieldsDto);
243	        rejectCityAtCapacity(owner.getCity());
244	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
245	        owner.setTelephone(telephone);
246	        String email = normalizeEmail(ownerFieldsDto.getEmail());
247	        owner.setEmail(email);
248	        owner.setPostcode(validatePostcode(ownerFieldsDto.getPostcode(), regionForCity(owner.getCity())));
249	        owner.setHouseholdId(computeHouseholdId(owner.getLastName(), owner.getPostcode()));
250	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
251	        rejectDuplicateIdentity(owner);
252	        if (!sharesHousehold) {
253	            rejectHouseholdDuplicate(owner);
254	        }
255	        applyPossibleDuplicate(owner, sharesHousehold);
256	        owner.setRegistrationDate(registrationDate);
257	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
258	        owner.setCustomerCode(generateCustomerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName()));
259	        this.clinicService.saveOwner(owner);
260	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
261	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
262	            owner.getMembershipLevel(), owner.getMembershipNumber());
263	        rememberIdempotentCreate(idempotencyKey, owner.getId());
264	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
265	        applyBulkSignupWarning(ownerDto);
266	        headers.setLocation(UriComponentsBuilder.newInstance()
267	            .path(OwnerMapper.OWNER_PATH_TEMPLATE).buildAndExpand(owner.getId()).toUri());
268	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
269	    }
270	
271	    /**
272	     * Serves a repeated create that carries an {@code Idempotency-Key} already seen on an earlier
273	     * successful create. When the key has a remembered owner that still exists, the originally created
274	     * owner is returned with {@code 200 OK} (carrying its {@code Location}) so the retry neither creates
275	     * a duplicate nor re-runs the create rules. A {@code null} or blank key, an unseen key, or a key
276	     * whose owner no longer exists yields {@code null}, signalling the caller to perform a normal create.
277	     *
278	     * @param idempotencyKey the {@code Idempotency-Key} header value, or {@code null} if absent
279	     * @return the originally created owner as a {@code 200 OK} response, or {@code null} to create normally
280	     */
281	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
282	        if (isBlank(idempotencyKey)) {
283	            return null;
284	        }
285	        Integer ownerId = idempotentCreateOwnerIds.get(idempotencyKey);
286	        if (ownerId == null) {
287	            return null;
288	        }
289	        Owner owner = this.clinicService.findOwnerById(ownerId);
290	        if (owner == null) {
291	            return null;
292	        }
293	        HttpHeaders headers = new HttpHeaders();
294	        headers.setLocation(UriComponentsBuilder.newInstance()
295	            .path(OwnerMapper.OWNER_PATH_TEMPLATE).buildAndExpand(owner.getId()).toUri());
296	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
297	        applyBulkSignupWarning(ownerDto);
298	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.OK);
299	    }
300	
301	    /**
302	     * Remembers the owner just created under its request's {@code Idempotency-Key}, so a later create
303	     * repeating that key is served the same owner ({@link #replayIdempotentCreate}). A {@code null} or
304	     * blank key is ignored, leaving that create non-idempotent.
305	     *
306	     * @param idempotencyKey the {@code Idempotency-Key} header value, or {@code null} if absent
307	     * @param ownerId        the id of the owner that was just created
308	     */
309	    private void rememberIdempotentCreate(String idempotencyKey, Integer ownerId) {
310	        if (!isBlank(idempotencyKey)) {
311	            idempotentCreateOwnerIds.put(idempotencyKey, ownerId);
312	        }
313	    }
314	
315	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
316	    @Override
317	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
318	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
319	        if (currentOwner == null) {
320	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
321	        }
322	        currentOwner.setAddress(ownerFieldsDto.getAddress());
323	        currentOwner.setCity(ownerFieldsDto.getCity());
324	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
325	        currentOwner.setLastName(ownerFieldsDto.getLastName());
326	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
327	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
328	        this.clinicService.saveOwner(currentOwner);
329	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
330	    }
331	
332	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
333	    @Transactional
334	    @Override
335	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
336	        Owner owner = this.clinicService.findOwnerById(ownerId);
337	        if (owner == null) {
338	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
339	        }
340	        owner.setDeleted(true);
341	        this.clinicService.saveOwner(owner);
342	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
343	    }
344	
345	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
346	    @Override
347	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
348	        Owner owner = this.clinicService.findOwnerById(ownerId);
349	        if (owner == null) {
350	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
351	        }
352	        HttpHeaders headers = new HttpHeaders();
353	        Pet pet = petMapper.toPet(petFieldsDto);
354	        owner.setId(ownerId);
355	        pet.setOwner(owner);
356	        pet.getType().setName(null);
357	        this.clinicService.savePet(pet);
358	        PetDto petDto = petMapper.toPetDto(pet);
359	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
360	            .buildAndExpand(pet.getId()).toUri());
361	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
362	    }
363	
364	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
365	    @Override
366	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
367	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
368	        if (currentOwner != null) {
369	            Pet currentPet = this.clinicService.findPetById(petId);
370	            if (currentPet != null) {
371	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
372	                currentPet.setName(petFieldsDto.getName());
373	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
374	                this.clinicService.savePet(currentPet);
375	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
376	            }
377	        }
378	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
379	    }
380	
381	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
382	    @Override
383	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
384	        HttpHeaders headers = new HttpHeaders();
385	        Visit visit = visitMapper.toVisit(visitFieldsDto);
386	        Pet pet = new Pet();
387	        pet.setId(petId);
388	        visit.setPet(pet);
389	        this.clinicService.saveVisit(visit);
390	        VisitDto visitDto = visitMapper.toVisitDto(visit);
391	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
392	            .buildAndExpand(visit.getId()).toUri());
393	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
394	    }
395	
396	
397	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
398	    @Override
399	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
400	        Owner owner = this.clinicService.findOwnerById(ownerId);
401	        if (owner != null) {
402	            Pet pet = owner.getPet(petId);
403	            if (pet != null) {
404	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
405	            }
406	        }
407	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
408	    }
409	
410	    /**
411	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
412	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
413	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
414	     *
415	     * @param ownerFieldsDto the submitted owner fields
416	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
417	     *                                     name of every offending field
418	     */
419	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
420	        List<String> missingFields = new ArrayList<>();
421	        if (isBlank(ownerFieldsDto.getFirstName())) {
422	            missingFields.add("firstName");
423	        }
424	        if (isBlank(ownerFieldsDto.getLastName())) {
425	            missingFields.add("lastName");
426	        }
427	        if (!hasAddress(ownerFieldsDto)) {
428	            missingFields.add("address");
429	        }
430	        if (isBlank(ownerFieldsDto.getCity())) {
431	            missingFields.add("city");
432	        }
433	        if (isBlank(ownerFieldsDto.getTelephone())) {
434	            missingFields.add("telephone");
435	        }
436	        if (!missingFields.isEmpty()) {
437	            throw new InvalidOwnerFieldsException(missingFields);
438	        }
439	    }
440	
441	    private boolean isBlank(String value) {
442	        return value == null || value.isBlank();
443	    }
444	
445	    /**
446	     * Reports whether an existing owner has not been soft-deleted. The create endpoint's duplicate
447	     * and identity checks consider only live owners, so an owner flagged {@code deleted} no longer
448	     * blocks a new owner that would otherwise match it.
449	     *
450	     * @param owner an existing owner
451	     * @return {@code true} unless the owner is flagged deleted
452	     */
453	    private boolean isNotDeleted(Owner owner) {
