625	    /**
626	     * Builds the owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is
627	     * the region code derived from the owner's postcode ({@link #regionForPostcode}, {@code 'UNKNOWN'}
628	     * when the postcode is absent or in no known range), and {@code HASH8} is the first eight
629	     * upper-cased hex characters of the SHA-256 digest of the owner's normalized telephone followed by
630	     * the last name (e.g. {@code 'NSW-1A2B3C4D'}). The identity carries no sequence number, so the
631	     * same postcode region, telephone and last name always yield the same customer code.
632	     *
633	     * <p>If the computed code collides with an existing owner's {@code customerCode}, it is
634	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes
635	     * it unique, so distinct owners always receive distinct customer codes.
636	     *
637	     * @param postcode  the owner's validated postcode, or {@code null} if none was supplied
638	     * @param telephone the owner's normalized (E.164) telephone
639	     * @param lastName  the owner's last name
640	     * @return the formatted, de-duplicated customer code
641	     */
642	    private String generateCustomerCode(String postcode, String telephone, String lastName) {
643	        String region = regionForPostcode(postcode);
644	        String hash8 = hashHex(telephone + lastName, 8);
645	        String baseCode = region + "-" + hash8;
646	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
647	            .map(Owner::getCustomerCode)
648	            .filter(Objects::nonNull)
649	            .collect(Collectors.toSet());
650	        if (!existingCodes.contains(baseCode)) {
651	            return baseCode;
652	        }
653	        int n = 2;
654	        while (existingCodes.contains(baseCode + "-" + n)) {
655	            n++;
656	        }
657	        return baseCode + "-" + n;
658	    }
