683	    /**
684	     * Resolves the region code for a city via the fixed {@link #CITY_REGION} table
685	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), returning {@code 'UNKNOWN'}
686	     * when the city is not listed. Used to validate an owner's optional postcode against its city's
687	     * region.
688	     *
689	     * @param city the owner's city
690	     * @return the region code, or {@code 'UNKNOWN'}
691	     */
692	    private String regionForCity(String city) {
693	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
694	    }
