842	    /**
843	     * Flags the owner being created as a possible (soft) duplicate. A possible duplicate is an owner
844	     * that is not a hard duplicate (its identity key is unique, so it has already passed
845	     * {@link #rejectDuplicateIdentity}) yet belongs to the same household as an existing owner — that
846	     * is, it carries the same computed {@code householdId} (derived from the last name and postcode) —
847	     * while carrying a different telephone. When such a match exists the owner is created with
848	     * {@code possibleDuplicate} set to {@code true} and {@code possibleDuplicateOf} set to the matching
849	     * owner's id (the earliest matching owner by id); otherwise {@code possibleDuplicate} is
850	     * {@code false} and {@code possibleDuplicateOf} is left unset.
851	     *
852	     * <p>An owner that declares household membership via {@code sharesHousehold} is never flagged: a
853	     * declared household member is not a suspected duplicate. (Without that declaration a same-household
854	     * owner is rejected outright by {@link #rejectHouseholdDuplicate}, so no suspected-duplicate match
855	     * survives for a created owner either.)
856	     *
857	     * @param owner           the owner being created, with its household id and telephone already set
858	     * @param sharesHousehold whether the owner declared itself a member of an existing household
859	     */
860	    private void applyPossibleDuplicate(Owner owner, boolean sharesHousehold) {
861	        owner.setPossibleDuplicate(false);
862	        if (sharesHousehold) {
863	            return;
864	        }
865	        String householdId = owner.getHouseholdId();
866	        if (householdId == null || householdId.isBlank()) {
867	            return;
868	        }
869	        String telephone = owner.getTelephone();
870	        Owner match = this.clinicService.findAllOwners().stream()
871	            .filter(this::isNotDeleted)
872	            .filter(existing -> householdId.equals(existing.getHouseholdId())
873	                && !Objects.equals(telephone, existing.getTelephone()))
874	            .min(Comparator.comparingInt(Owner::getId))
875	            .orElse(null);
876	        if (match != null) {
877	            owner.setPossibleDuplicate(true);
878	            owner.setPossibleDuplicateOf(match.getId());
879	        }
880	    }
