882	    /**
883	     * Computes the owner's deterministic {@code householdId}: the first twelve upper-cased hex
884	     * characters of the SHA-256 digest of the normalized last name and the postcode joined by a
885	     * {@code '|'}. Because the value derives only from the last name and postcode, every owner that
886	     * shares both automatically shares the same household id, so the household is keyed on
887	     * {@code (lastName, postcode)} with no opt-in required. The last name is normalized for comparison
888	     * (trimmed, internal whitespace collapsed, lower-cased) so values differing only in case or spacing
889	     * still land in the same household.
890	     *
891	     * @param lastName the owner's last name
892	     * @param postcode the owner's validated postcode, or {@code null} if none was supplied
893	     * @return the derived household id, or {@code null} when the owner has no postcode and so belongs
894	     *         to no postcode-keyed household
895	     */
896	    private String computeHouseholdId(String lastName, String postcode) {
897	        if (postcode == null) {
898	            return null;
899	        }
900	        return hashHex(normalizeForComparison(lastName) + "|" + postcode, 12);
901	    }
