944	    /**
945	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
946	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
947	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
948	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
949	     * This normalized value is what gets stored and returned.
950	     *
951	     * @param address the raw address value submitted by the client, possibly {@code null}
952	     * @return the normalized address, or an empty string if {@code address} is {@code null}
953	     */
954	    private String normalizeAddress(String address) {
955	        if (address == null) {
956	            return "";
957	        }
958	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
959	        if (collapsed.isEmpty()) {
960	            return collapsed;
961	        }
962	        String[] tokens = collapsed.split(" ");
963	        StringBuilder normalized = new StringBuilder(collapsed.length());
964	        for (int i = 0; i < tokens.length; i++) {
965	            if (i > 0) {
966	                normalized.append(' ');
967	            }
968	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
969	        }
970	        return normalized.toString();
971	    }
972	
973	    /**
974	     * Reports whether the submitted owner supplies an address in either accepted form: a non-blank
975	     * structured {@code addressLine1}, or a non-blank flat {@code address}. The structured form is
976	     * preferred when present, but either satisfies the address requirement, keeping the create
977	     * contract backward-compatible with earlier flat-address-only owners.
978	     *
979	     * @param ownerFieldsDto the submitted owner fields
980	     * @return {@code true} if an address is supplied in either form
981	     */
982	    private boolean hasAddress(OwnerFieldsDto ownerFieldsDto) {
983	        return !isBlank(ownerFieldsDto.getAddressLine1())
984	            || !isBlank(normalizeAddress(ownerFieldsDto.getAddress()));
985	    }
986	
987	    /**
988	     * Applies the owner's address, preferring the structured form over the flat one. When a non-blank
989	     * {@code addressLine1} is supplied, it and the optional {@code addressLine2} are normalized
990	     * ({@link #normalizeAddress}) and stored, and the owner's composed {@code address} is set to the
991	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
992	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized
993	     * and stored and the structured lines are left unset. This keeps earlier flat-address owners
994	     * working while letting everything that reads the address use the composed, normalized value.
995	     *
996	     * @param owner          the owner being created
997	     * @param ownerFieldsDto the submitted owner fields
998	     */
999	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
1000	        if (!isBlank(ownerFieldsDto.getAddressLine1())) {
1001	            String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
1002	            String line2 = isBlank(ownerFieldsDto.getAddressLine2())
1003	                ? null
1004	                : normalizeAddress(ownerFieldsDto.getAddressLine2());
1005	            owner.setAddressLine1(line1);
1006	            owner.setAddressLine2(line2);
1007	            owner.setAddress(line2 != null ? line1 + " " + line2 : line1);
1008	        } else {
1009	            owner.setAddressLine1(null);
1010	            owner.setAddressLine2(null);
1011	            owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
1012	        }
1013	    }
1014	}
